import { Component } from 'react'
import PropTypes from 'prop-types'
import FullPageModal from '../../../../../../../components/FullPageModal'
import { LANG_STRINGS } from '../../../../../../../lang'
import { Button, CustomText } from '../../../../../../../components'
import { InformationModelStyle } from './index.style'
import DownlineAgentCard from '../DownlineAgentCard'
import { ARROW_DOWN_WHITE, BISMO } from '../../../../../../../images'
import { Row } from '../../../../../../../commonStyle/index.style'

class InformationModal extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    onCloseModal: PropTypes.func
  }

  constructor (props) {
    super(props)
    const isAggregatorAgent = props.isAggregatorAgent

    this.state = {
      information: [
        {
          title: 'Polis',
          description: 'Jumlah polis terjual oleh mitra dan downline-nya'
        },
        {
          title: 'Agen Downline',
          description: 'Jumlah anggota di bawah mitra'
        },
        {
          title: isAggregatorAgent ? 'Premi Downline' : 'Polis Downline',
          description: isAggregatorAgent ? 'Premium Kebijakan yang dijual oleh anggota di bawah mitra' : 'Jumlah polis terjual oleh anggota mitra'
        },
        {
          title: isAggregatorAgent ? 'Premi' : 'Poin',
          description: isAggregatorAgent ? 'Premium oleh mitra dan anggota di bawah mitra' : 'Jumlah poin yang diperoleh dari mitra dan pendapatan anggota'
        }
      ]
    }
  }

  render () {
    const { showModal, onCloseModal, isAggregatorAgent } = this.props
    const { information } = this.state
    return (
      <FullPageModal
        onCloseModal={onCloseModal}
        showModal={showModal}
        header={LANG_STRINGS.information}
        isTransparent
      >
        <InformationModelStyle>
          <DownlineAgentCard
            downlineAgent={{
              name: 'Andreas',
              self_summary_from_ancestor: {
                total_policies: 5,
                total_points: 4
              },
              downline_summary_from_ancestor: {
                total_policies: 5,
                total_points: 4
              },
              agent_depth: 1,
              total_agent_downline: 10,
              profile_url: BISMO
            }}
            isAggregatorAgent={isAggregatorAgent}
            isDummy
          />
          <img className='arrow-down-white' src={ARROW_DOWN_WHITE} alt='' />
          <div className='information'>
            {
              information.map((info, index) => (
                <CustomText key={`info_${index}`} bottom='6px'>
                  <b>{index + 1}. {info.title}:</b>&nbsp; {info.description}
                </CustomText>
              ))
            }
          </div>
          <Row align='center' justify='center'>
            <Button onClick={onCloseModal} className='info-btn'>
              {LANG_STRINGS.okay}
            </Button>
          </Row>
        </InformationModelStyle>
      </FullPageModal>
    )
  }
}

export default InformationModal
