import { Component } from 'react'
import PropTypes from 'prop-types'
import { DownlineAgentCardStyle } from './index.style'
import { CustomText } from '../../../../../../../components'
import Avatar from '../../../../../../../components/Avatar'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { Row, EditCircleIcon } from '../../../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../../../lang'
import get from 'lodash/get'
import { formatMoney } from '../../../../../../../helpers/utility'

class DownlineAgentCard extends Component {
  static propTypes = {
    downlineAgent: PropTypes.object,
    isDummy: PropTypes.bool,
    onClick: PropTypes.func
  }

  renderTitleValueBox = (title, value, count) => {
    const { isDummy } = this.props
    return (
      <Row width='100%'>
        <CustomText color={AgentColorPallette.fontSemiGrey}>
          {title}:&nbsp;
        </CustomText>
        <CustomText color={AgentColorPallette.black} weight={700}>
          {value}
        </CustomText>
        {
          isDummy && <EditCircleIcon width='16px' size='8px' marginLeft='3px'>{count}</EditCircleIcon>
        }
      </Row>
    )
  }

  render () {
    const { downlineAgent, onClick, isDummy, showArrow, isAggregatorAgent } = this.props

    return (
      <DownlineAgentCardStyle onClick={onClick} width={isDummy && '80%'}>
        <Avatar imgUrl={downlineAgent.profile_url} isIcon={!isDummy} />
        <Row justify='space-between' className='downline-right-section'>
          <div>
            <CustomText color={AgentColorPallette.black} weight={800} size='16px'>
              {downlineAgent.name}
            </CustomText>
            {
              this.renderTitleValueBox(
                LANG_STRINGS.policies,
                get(downlineAgent, 'self_summary_from_ancestor.total_policies', ''),
                1
              )
            }
            {
              (downlineAgent.agent_depth < 3 || isAggregatorAgent) && this.renderTitleValueBox(
                isAggregatorAgent ? (`${LANG_STRINGS.downline} ${downlineAgent.name}`) : (`${downlineAgent.name}'s ${LANG_STRINGS.downline}`),
                get(downlineAgent, 'total_agent_downline', ''),
                2
              )
            }
            {
              (downlineAgent.agent_depth < 3 || isAggregatorAgent) && this.renderTitleValueBox(
                isAggregatorAgent ? LANG_STRINGS.premiumDownline : LANG_STRINGS.policyDownline,
                isAggregatorAgent ? get(downlineAgent, 'downline_summary_from_ancestor.total_points', '')
                  : get(downlineAgent, 'downline_summary_from_ancestor.total_policies', ''),
                3
              )
            }
          </div>
          <div>
            <Row align='center'>
              <CustomText color={AgentColorPallette.black} size='18px' weight={800}>
                {
                  formatMoney(get(downlineAgent, 'downline_summary_from_ancestor.total_points', '') +
                    get(downlineAgent, 'self_summary_from_ancestor.total_points', ''),
                  0,
                  ''
                  )
                }
              </CustomText>
              {
                isDummy && <EditCircleIcon width='16px' size='8px'>{4}</EditCircleIcon>
              }
            </Row>
            <CustomText color={AgentColorPallette.fontSemiGrey} weight={700}>
              {isAggregatorAgent ? LANG_STRINGS.premium : LANG_STRINGS.pointsSmall}
            </CustomText>
          </div>

        </Row>
        {
          showArrow &&
            <div className='downline-forward-icon'>
              <i className='fas fa-arrow-right' />
            </div>
        }
      </DownlineAgentCardStyle>
    )
  }
}

export default DownlineAgentCard
