import { Component } from 'react'
import PropTypes from 'prop-types'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText, Button } from '../../../../../components'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../lang'
import { REFER_URL } from '../../../../../constants/appUrls'
import { ShareReferralCodeStyle } from './index.style'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { copyToClipboard } from '../../../../../helpers/copyToClipboard'

class ShareReferralCode extends Component {
  static propTypes = {
    referralCode: PropTypes.string,
    bottom: PropTypes.string
  }

  handleShare = () => {
    const contentForShare = `
      ${LANG_STRINGS.shareBtnText} ${this.props.referralCode}
      ${REFER_URL}&link=${window.location.origin}?referral_code=${this.props.referralCode}
    `
    if (navigator.share) {
      // Web Share API is supported
      navigator.share({
        title: LANG_STRINGS.referNEarn,
        text: contentForShare
      })
        .catch(console.error)
    } else if (window.PPBridge) {
      window.PPBridge.share(LANG_STRINGS.share, contentForShare)
    } else {
      // Fallback
      NotificationManager.error(ERROR_LANG.shareOptionNotSupport)
    }
  }

  handleCopyToClipboard = () => {
    // this handle copy referral code
    const referralUrl = `${REFER_URL}&link=${window.location.origin}?referral_code=${this.props.referralCode}`
    if (window.PPBridge) {
      // this for android device
      window.PPBridge.copy(referralUrl)
    } else {
      if (navigator.clipboard) {
        navigator.clipboard.writeText(referralUrl).then(function () {
          NotificationManager.success('Menyalin ke clipboard berhasil')
        }, function () {
          NotificationManager.success('Gagal Menyalin')
        })
      } else {
        // this is helpful to copy to data
        if (copyToClipboard(referralUrl)) {
          NotificationManager.success('Menyalin ke clipboard berhasil')
        }
      }
    }
  }

  render () {
    const { bottom } = this.props
    return (
      <ShareReferralCodeStyle align='center' justify='space-between' padding='0' bottom={bottom}>
        <Row className='bottom-action' justify='space-between'>
          <div>
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              size='12px'
            >
              {LANG_STRINGS.yourReferralCode}
            </CustomText>
            <CustomText
              color={AgentColorPallette.black}
              size='16px'
              weight={800}
            >
              {this.props.referralCode}
            </CustomText>
          </div>
          <Row align='center' justify='space-between' className='earn-btn-box'>
            <Button className='earn-btn' onClick={this.handleCopyToClipboard}>
              {LANG_STRINGS.copy}
            </Button>
            <Button className='earn-btn' onClick={this.handleShare}>
              {LANG_STRINGS.share}
            </Button>
          </Row>
        </Row>
        <NotificationContainer />
      </ShareReferralCodeStyle>
    )
  }
}

export default ShareReferralCode
