import { Component } from 'react'
import PropTypes from 'prop-types'
import { LevelHeaderStyle } from './index.style'
import { range } from 'lodash/util'
import { LANG_STRINGS } from '../../../../../../../lang'
import { Row } from '../../../../../../../commonStyle/index.style'

class LevelHeader extends Component {
  static propTypes = {
    active: PropTypes.number,
    onLevelClick: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.state = {
      levels: 3
    }
  }

  handleLevelClick = (active, level) => {
    // here we handle active and inactive level
    if (this.props.onLevelClick) {
      this.props.onLevelClick(active, level)
    }
  }

  render () {
    const { levels } = this.state
    const { active } = this.props
    return (
      <LevelHeaderStyle>
        {
          range(levels).map(value => (
            <>
              <div key={value} onClick={() => this.handleLevelClick(active, value)} className={`level-name ${(value <= active) && 'active'}`}>
                {LANG_STRINGS.level}&nbsp;{value + 1}
              </div>
              {
                (value < (levels - 1)) && (
                  <Row className='arrow-section' align='center' justify='center'>
                    <div className={`level-arrow ${(value <= (active - 1)) && 'level-arrow-active '}`} />
                    <div className={`arrow ${(value <= (active - 1)) && 'active'}`}>
                      {'>'}
                    </div>
                  </Row>
                )
              }
            </>
          ))
        }
      </LevelHeaderStyle>
    )
  }
}

export default LevelHeader
