import { useState, useRef, useCallback } from 'react'
import { Row } from '../../../../../../../commonStyle/index.style'
import { CustomCollapse, CustomText } from '../../../../../../../components'
import ButtonWithIcon from '../../../../../../../components/ButtonWithIcon'
import DobInput from '../../../../../../../components/DobInput'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { SEND_GOLD_ICON } from '../../../../../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../../lang'
import { AdditionalInfoStyle } from './index.style'

function AdditionalInfoSheet (props) {
  const { onApply, handleShowSnackbar, resetFilter } = props
  const [selectedPeriod, setSelectedPeriod] = useState('THIS_MONTH')

  const startDateRef = useRef(null)
  const endDateRef = useRef(null)
  const startDateVal = useRef('')
  const endDateVal = useRef('')

  const [isSetPeriodFilter, setPeriodFilter] = useState(true)

  const handleFilterDate = useCallback((date, type) => {
    if (type === 'start') {
      startDateVal.current = date
    } else {
      endDateVal.current = date
    }
  }, [
  ])

  const handleReset = useCallback(() => {
    if (endDateRef.current) {
      endDateRef.current.resetDate()
    }
    if (startDateRef.current) {
      startDateRef.current.resetDate()
    }

    endDateVal.current = ''
    startDateVal.current = ''
    setSelectedPeriod('')
    setPeriodFilter(false)
    resetFilter()
  }, [resetFilter])

  const handleTheApply = useCallback(() => {
    if (selectedPeriod === 'SELECT_DATE') {
      if (startDateRef.current.state.showError || endDateRef.current.state.showError || !startDateVal.current || !endDateVal.current) {
        handleShowSnackbar(true, ERROR_LANG.invalidDateFormat, true)
        return
      }
    }

    onApply({
      startDate: startDateVal.current,
      endDate: endDateVal.current,
      selectedPeriod
    })
  }, [
    onApply, selectedPeriod,
    handleShowSnackbar
  ])

  const handleSelectedPeriod = (type) => {
    setSelectedPeriod(type)
    setPeriodFilter(true)
  }

  const renderSelectPeriod = (title, type) => {
    return (
      <CustomText
        color={AgentColorPallette.black}
        className={`period-section ${type === selectedPeriod ? 'selected-period' : ''}`}
        onClick={() => handleSelectedPeriod(type)}
      >
        {title}
      </CustomText>
    )
  }

  return (
    <AdditionalInfoStyle>
      <Row align='center' justify='space-between'>
        <CustomText color={AgentColorPallette.black} weight={700} size='15px'>
          {LANG_STRINGS.filter}
        </CustomText>
        <CustomText className='cursor' color={AgentColorPallette.blood} size='13px' onClick={handleReset}>
          {LANG_STRINGS.reset}
        </CustomText>
      </Row>

      <div className='filters-container'>
        <CustomCollapse hideBorders headingClass='heading' label='Periode' isOpened>
          <Row align='center'>
            {
              renderSelectPeriod(LANG_STRINGS.thisMonth, 'THIS_MONTH')
            }
            &nbsp;&nbsp;&nbsp;
            {
              renderSelectPeriod(LANG_STRINGS.lastMonth, 'LAST_MONTH')
            }
            &nbsp;&nbsp;&nbsp;
            {
              renderSelectPeriod(LANG_STRINGS.threeMontAgo, 'LAST_THREE_MONTH')
            }
          </Row>
          <Row align='center' className='mt-10'>
            {
              renderSelectPeriod(LANG_STRINGS.sixMonthAgo, 'SIX_MONTH')
            }
            &nbsp;&nbsp;&nbsp;
            {
              renderSelectPeriod(LANG_STRINGS.selectDate, 'SELECT_DATE')
            }
          </Row>
          {
            selectedPeriod === 'SELECT_DATE' &&
              <Row className='date-section'>
                <div className='date'>
                  <CustomText
                    size='10px'
                    color={AgentColorPallette.black}
                    weight={600}
                  >
                    {LANG_STRINGS.from}
                  </CustomText>
                  <DobInput
                    name='startDate'
                    ref={startDateRef}
                    minDate='01/01/2019'
                    onDobSelect={(date) => handleFilterDate(date, 'start')}
                    displayBorder
                    borderColor={AgentColorPallette.borderGrey}
                    maxDate={new Date()}
                    errorMsg={ERROR_LANG.pleaseEnterTodayDateOrPreviousDate}
                  />
                </div>

                <div className='date'>
                  <CustomText
                    size='10px'
                    color={AgentColorPallette.black}
                    weight={600}
                  >
                    {LANG_STRINGS.to}
                  </CustomText>
                  <DobInput
                    name='endDate'
                    ref={endDateRef}
                    onDobSelect={(date) => handleFilterDate(date, 'end')}
                    displayBorder
                    borderColor={AgentColorPallette.borderGrey}
                    maxDate={new Date()}
                    errorMsg={ERROR_LANG.pleaseEnterTodayDateOrPreviousDate}
                  />
                </div>
              </Row>
          }
        </CustomCollapse>
      </div>
      <ButtonWithIcon
        disabled={!isSetPeriodFilter}
        text={LANG_STRINGS.apply}
        icon={SEND_GOLD_ICON}
        iconRight
        onClick={handleTheApply}
      />
    </AdditionalInfoStyle>
  )
}

export default AdditionalInfoSheet
