import { Component } from 'react'
import PropTypes from 'prop-types'
import { DownlineAgentHeaderStyle, DownlineAgentPoliciesStyle } from './index.style'
import Avatar from '../../../../../../../components/Avatar'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../../lang'
import get from 'lodash/get'
import { formatMoney } from '../../../../../../../helpers/utility'

class DownlineAgentHeader extends Component {
  static propTypes = {
    downlineAgent: PropTypes.object
  }

  render () {
    const { downlineAgent = {} } = this.props
    return (
      <>
        <DownlineAgentHeaderStyle>
          <Avatar isIcon />
          <div>
            <CustomText color={AgentColorPallette.white} size='14px' weight={800}>
              {downlineAgent.name}
            </CustomText>
            <CustomText>
              {`${LANG_STRINGS.policiesSoldByAgent} ${downlineAgent.name}`}
            </CustomText>
            <CustomText weight={800}>
              {get(downlineAgent, 'self_summary_from_ancestor.total_policies', 0)}&nbsp;
              {LANG_STRINGS.policies}&nbsp;/&nbsp;
              {formatMoney(get(downlineAgent, 'self_summary_from_ancestor.total_points', 0), 3, '')}&nbsp;
              {LANG_STRINGS.pointsSmall}
            </CustomText>
            <CustomText top='10px'>
              <a href={`tel:${downlineAgent.phone_no}`}>P:&nbsp;{downlineAgent.phone_no}</a>
            </CustomText>
            <CustomText>
              <a href={`mailto:${downlineAgent.email}`}>E:&nbsp;{downlineAgent.email}</a>
            </CustomText>
          </div>
        </DownlineAgentHeaderStyle>
        {
          (downlineAgent.agent_depth !== 3) && (
            <DownlineAgentPoliciesStyle>
              <CustomText
                className='downline-agent-total-policy'
                weight={800}
                textAlign='center'
              >
                {LANG_STRINGS.totalPolicies}:&nbsp;
                {
                  get(downlineAgent, 'self_summary_from_ancestor.total_policies', 0) +
                  get(downlineAgent, 'downline_summary_from_ancestor.total_policies', 0)
                }
              </CustomText>
              <CustomText weight={800}>|</CustomText>
              <CustomText
                className='downline-agent-total-policy'
                weight={800}
                textAlign='center'
              >
                {LANG_STRINGS.totalPoints}:&nbsp;
                {
                  formatMoney(
                    get(downlineAgent, 'self_summary_from_ancestor.total_points', 0) +
                    get(downlineAgent, 'downline_summary_from_ancestor.total_points', 0),
                    3,
                    ''
                  )
                }
              </CustomText>
            </DownlineAgentPoliciesStyle>
          )
        }
      </>
    )
  }
}

export default DownlineAgentHeader
