import { useState, useEffect, useCallback, useRef } from 'react'
import { connect } from 'react-redux'
import Cookies from 'universal-cookie'
import get from 'lodash/get'
import size from 'lodash/size'
import { Container, CustomText } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import InformationModal from './components/InformationModal'
import { DOWNLINE_INFO } from '../../../../../constants/cookies'
import { MyDownlineStyle } from './index.style'
import { getQueryParams } from '../../../../../helpers/utility'
import LevelHeader from './components/LevelHeader'
import DownlineAgentHeader from './components/DownlineAgentHeader'
import userActions from '../../../../../redux/user/action'
import MyDownlineHeaderCard from './components/MyDownlineHeaderCard'
import { Row, DisplayCircleIcon } from '../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { ImageUrl, INFO } from '../../../../../images'
import DownlineAgentCard from './components/DownlineAgentCard'
import NoDownline from './components/NoDownLine'
import DownlinePeakLevel from './components/DownlinePeakLevel'
import { useGlobalContextValue } from '../../../../../contextProvider/GlobalContext'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import AdditionalInfoSheet from './components/AdditionalInfoSheet'
import moment from 'moment'
import ShowSnackbar from '../../../../../components/ShowNotification'
import CircularLoader from '../../../../../components/CircularLoader'
import ShareReferralCode from '../../components/ShareReferralCode'

const cookies = new Cookies()
const {
  getDownline, getDownlineChild, getAggregatorDownline,
  getAggregatorDownlineBusiness, resetUserStore
} = userActions

function MyDownline (props) {
  // this is the function for downline hooks
  const {
    getDownlineLoader, getDownlineChildListLoader, getAggregatorDownlineLoader,
    getAggregatorDownlineBusinessLoader, agentDownLineSummary = {}, agentDetails,
    location = {}, getDownline, getAggregatorDownline, resetUserStore,
    getAggregatorDownlineBusiness, agentAggregatorBusiness, agentAggregatorDownLineList,
    downlineChilds, agentDownLineChildMeta, getDownlineChild, agentAggregatorDownLineMeta
  } = props
  // if this value false then never show the modal on page start
  const isNeedToShowModal = (cookies.get(DOWNLINE_INFO) !== 'false')
  const [showModal, setModalState] = useState(isNeedToShowModal)
  // if the level is not exist in the url query param then set the value to 0
  // 0 is the initial level for the login agent
  const activeLevelFromQueryParam = parseInt(getQueryParams('level'), 10) || 0
  const [activeLevel, setActiveLevel] = useState(activeLevelFromQueryParam)
  const [showPeakLevel, setShowPeakLevel] = useState(false)
  const [showBottomSheet, setShowBottomSheet] = useState(false)
  const [selectedFilter, setSelectedFilter] = useState(LANG_STRINGS.thisMonth)

  const filterStartDate = useRef(moment().startOf('month').format('YYYY-MM-DD'))
  const filterEndDate = useRef(moment(new Date()).format('YYYY-MM-DD'))
  const elementState = useRef({})
  const listConfig = useRef({
    page: 1,
    page_size: 10
  })

  const placeholder = useRef()
  const isFirstCall = useRef(true)
  const observerRef = useRef()

  const [{
    isAggregatorAgent
  }] = useGlobalContextValue()

  const [snackBar, setSnackBar] = useState({
    showBar: false,
    barMsg: '',
    isBarMsgError: true
  })

  const handleShowSnackbar = (isShow, text, isError = true) => {
    setSnackBar({
      showBar: isShow,
      barMsg: text,
      isBarMsgError: isError
    })
    setTimeout(() => {
      setSnackBar({
        showBar: false
      })
    }, 4000)
  }

  useEffect(() => {
    return () => {
      resetUserStore(['agentAggregatorDownLineList', 'agentAggregatorDownLineMeta', 'agentAggregatorDownLineListStatus'])
    }
  }, [resetUserStore])

  useEffect(() => {
    if (!isAggregatorAgent) {
      const level = parseInt(getQueryParams('level'), 10) || 0
      const agentCode = getQueryParams('agentcode')
      const showPeak = getQueryParams('showpeak') === 'true'
      if (level === 2 && showPeak) {
        setShowPeakLevel(showPeak)
      } else if (!showPeak) {
        setShowPeakLevel(false)
        setActiveLevel(level)
      }
      getDownline({
        parent: agentCode,
        level
      })
      getDownlineChild({
        parent: agentCode,
        level,
        ...listConfig.current
      })
    }
  }, [getDownline, location,
    isAggregatorAgent, getDownlineChild
  ])

  useEffect(() => {
    if (isFirstCall.current) {
      if (isAggregatorAgent) {
        getAggregatorDownlineBusiness()
        getAggregatorDownline({
          start_date: filterStartDate.current,
          end_date: filterEndDate.current,
          page: listConfig.current.page,
          page_size: 10
        })
      }
      isFirstCall.current = false
    }

    const callback = (entries) => {
      const y = entries[0].boundingClientRect.y
      const numberPages = agentDownLineChildMeta?.num_page || agentAggregatorDownLineMeta?.num_page
      if (elementState.current.prevY > y && (listConfig.current.page < numberPages)) {
        listConfig.current.page = listConfig.current.page + 1
        if (isAggregatorAgent) {
          getAggregatorDownline({
            start_date: filterStartDate.current,
            end_date: filterEndDate.current,
            page: listConfig.current.page,
            page_size: 10
          })
        } else {
          const agentCode = getQueryParams('agentcode')
          getDownlineChild({
            parent: agentCode,
            page: listConfig.current.page,
            level: parseInt(getQueryParams('level'), 10) || 0,
            page_size: 10
          })
        }
      }
      elementState.current.prevY = y
    }

    const observer = new IntersectionObserver(callback, {
      root: null,
      rootMargin: '0px',
      threshold: 1.0
    })
    observerRef.current = observer
    if (placeholder.current) {
      observer.observe(placeholder.current)
    }

    return () => {
      observer.current && observer.current.disconnect()
    }
  }, [getAggregatorDownline, isAggregatorAgent,
    filterStartDate, filterEndDate,
    getAggregatorDownlineBusiness,
    getDownlineChild, agentDownLineChildMeta,
    agentAggregatorDownLineMeta
  ])

  useEffect(() => {
    return () => {
      observerRef.current.disconnect()
    }
  }, [])

  const handleResetFilter = useCallback(() => {
    setSelectedFilter('')
    setShowBottomSheet(false)
    getAggregatorDownline({
      isFilterApply: true
    })
  }, [getAggregatorDownline])

  const handleToggleModal = () => {
    // showModal is the state that has been updated and function is called every
    // time when we set any state of the component
    setModalState(!showModal)
    // here we are setting tht cookie
    cookies.set(DOWNLINE_INFO, 'false', {
      path: '/',
      maxAge: 60 * 60 * 24 * 365 // store for year
    })
  }

  const handleCardClick = useCallback((downlineAgent) => {
    if (!isAggregatorAgent) {
      // handle the card click
      listConfig.current.page = 1
      if (activeLevel === 2) {
        props.history.push({
          pathname: `/my-downline/?level=${activeLevel}&agentcode=${downlineAgent.agent_code}&showpeak=true`
        })
      } else {
        props.history.push({
          pathname: `/my-downline/?level=${activeLevel + 1}&agentcode=${downlineAgent.agent_code}`
        })
      }
    }
  }, [activeLevel,
    props.history, isAggregatorAgent
  ])

  const getDownlinesAndInfo = (total) => {
    return (
      <Row align='center' justify='space-between' className='downline-info'>
        <Row align='center'>
          <CustomText size='14px' color={AgentColorPallette.black} weight={800}>
            {total}&nbsp;
          </CustomText>
          <CustomText color={AgentColorPallette.fontSemiGrey}>
            {isAggregatorAgent ? LANG_STRINGS.downlineLangsung : LANG_STRINGS.directDownlines}
          </CustomText>
        </Row>
        <DisplayCircleIcon width='20px' height='20px' onClick={handleToggleModal}>
          <img src={INFO} alt='' />
        </DisplayCircleIcon>
      </Row>
    )
  }

  const getAgentCards = useCallback(() => {
    if (isAggregatorAgent) {
      if (get(agentAggregatorDownLineMeta, 'total_records', 0) === 0) {
        return (
          <NoDownline
            activeLevel={activeLevel}
            isAggregatorAgent
          />
        )
      } else {
        return (
          agentAggregatorDownLineList.map((agent) => {
            return (
              <DownlineAgentCard
                key={agent.agent_code}
                downlineAgent={agent}
                onClick={() => handleCardClick(agent)}
                showArrow={false}
                isAggregatorAgent={isAggregatorAgent}
              />
            )
          })
        )
      }
    } else {
      return (
        (!showPeakLevel) && (
          size(downlineChilds) ? downlineChilds.map(agent => (
            <DownlineAgentCard
              key={agent.agent_code}
              downlineAgent={agent}
              onClick={() => handleCardClick(agent)}
              showArrow
            />
          )) : (getDownlineLoader === false) && <NoDownline activeLevel={activeLevel} />
        )
      )
    }
  }, [isAggregatorAgent, activeLevel,
    agentAggregatorDownLineList, downlineChilds,
    getDownlineLoader, handleCardClick,
    showPeakLevel, agentAggregatorDownLineMeta
  ])

  const handleFilter = useCallback((showFilter) => {
    setShowBottomSheet(showFilter)
  }, [])

  const getFilterText = useCallback((filterType) => {
    switch (filterType) {
      case 'THIS_MONTH':
        return LANG_STRINGS.thisMonth
      case 'LAST_MONTH':
        return LANG_STRINGS.lastMonth
      case 'LAST_THREE_MONTH':
        return LANG_STRINGS.threeMontAgo
      case 'SIX_MONTH':
        return LANG_STRINGS.sixMonthAgo
      case 'SELECT_DATE':
        return LANG_STRINGS.selectDate
      default:
        return ''
    }
  }, [])

  const getFilterDates = useCallback((filterType) => {
    let endDate = ''
    let startDate = ''

    switch (filterType) {
      case 'THIS_MONTH':
        startDate = moment().startOf('month').format('YYYY-MM-DD')
        endDate = moment(new Date()).format('YYYY-MM-DD')
        break
      case 'LAST_MONTH':
        startDate = moment().subtract(1, 'M').startOf('month').format('YYYY-MM-DD')
        endDate = moment().subtract(1, 'M').endOf('month').format('YYYY-MM-DD')
        break
      case 'LAST_THREE_MONTH':
        endDate = moment(new Date()).format('YYYY-MM-DD')
        startDate = moment().subtract(3, 'M').format('YYYY-MM-DD')
        break
      case 'SIX_MONTH':
        endDate = moment(new Date()).format('YYYY-MM-DD')
        startDate = moment().subtract(6, 'M').format('YYYY-MM-DD')
        break
      default:
        startDate = moment().startOf('month').format('YYYY-MM-DD')
        endDate = moment(new Date()).format('YYYY-MM-DD')
    }
    return {
      start_date: startDate,
      end_date: endDate
    }
  }, [])

  const handleChangeFilter = useCallback((filterData) => {
    if (filterData.selectedPeriod === 'SELECT_DATE') {
      getAggregatorDownline({
        start_date: moment(filterData.startDate, 'DD/MM/YYYY').format('YYYY-MM-DD'),
        end_date: moment(filterData.endDate, 'DD/MM/YYYY').format('YYYY-MM-DD'),
        isFilterApply: true,
        ...listConfig.current
      })
    } else {
      const { start_date: startDate, end_date: endDate } = getFilterDates(filterData.selectedPeriod)
      getAggregatorDownline({
        start_date: startDate,
        end_date: endDate,
        isFilterApply: true,
        ...listConfig.current
      })
      filterStartDate.current = startDate
      filterEndDate.current = endDate
    }
    setSelectedFilter(getFilterText(filterData.selectedPeriod))
    setShowBottomSheet(false)
  }, [getAggregatorDownline, getFilterText,
    getFilterDates
  ])

  return (
    <Container
      title={LANG_STRINGS.myDownline}
      activeTab='profile'
      displayBackButton
      loader={getDownlineLoader || getDownlineChildListLoader ||
        getAggregatorDownlineLoader || getAggregatorDownlineBusinessLoader}
    >
      <MyDownlineStyle>
        {
          !isAggregatorAgent &&
            <LevelHeader active={activeLevel} />
        }
        {
          (activeLevel > 0 && !isAggregatorAgent) &&
            <DownlineAgentHeader
              key={agentDownLineSummary.agent_code}
              downlineAgent={agentDownLineSummary}
            />
        }
        {
          (activeLevel === 0 || isAggregatorAgent) && (
            <MyDownlineHeaderCard
              data={{
                downlines: get(isAggregatorAgent ? agentAggregatorBusiness : agentDownLineSummary, 'total_agent_downline', 0),
                pointsEarned: (
                  get(isAggregatorAgent ? agentAggregatorBusiness : agentDownLineSummary, 'self_summary_from_ancestor.total_points', 0) +
                  get(isAggregatorAgent ? agentAggregatorBusiness : agentDownLineSummary, 'downline_summary_from_ancestor.total_points', 0)
                ),
                policies: (
                  get(isAggregatorAgent ? agentAggregatorBusiness : agentDownLineSummary, 'self_summary_from_ancestor.total_policies', 0) +
                  get(isAggregatorAgent ? agentAggregatorBusiness : agentDownLineSummary, 'downline_summary_from_ancestor.total_policies', 0)
                )
              }}
              isAggregatorAgent={isAggregatorAgent}
            />
          )
        }
        {
          isAggregatorAgent &&
            <Row
              className='filter-bar'
              justify='space-between'
              align='center'
              onClick={() => handleFilter('show')}
            >
              <Row align='center'>
                <CustomText
                  size='11px'
                  color={AgentColorPallette.fontDarkerGrey}
                >
                  Filter
                </CustomText>
                {
                  selectedFilter &&
                    <CustomText
                      color={AgentColorPallette.black}
                      className='selected-filter'
                    >
                      {selectedFilter}
                    </CustomText>
                }

              </Row>
              <img className='caret-down' src={ImageUrl.caretDown} alt='' />
            </Row>
        }
        {
          isAggregatorAgent &&
            <BottomActionSheet show={showBottomSheet} onCloseSheet={() => setShowBottomSheet(false)}>
              <AdditionalInfoSheet
                handleShowSnackbar={handleShowSnackbar}
                onApply={handleChangeFilter}
                resetFilter={handleResetFilter}
              />
            </BottomActionSheet>
        }
        {
          (!showPeakLevel || isAggregatorAgent) &&
          getDownlinesAndInfo(
            isAggregatorAgent
              ? get(agentAggregatorDownLineMeta, 'total_records', 0)
              : size(downlineChilds))
        }
        {
          getAgentCards()
        }
        {
          (activeLevel === 2 && showPeakLevel) && <DownlinePeakLevel />
        }
        {
          ((!!get(downlineChilds, 'length', 0) && (get(agentDownLineChildMeta, 'num_page', 0) !== listConfig.current.page)) ||
          (!!get(agentAggregatorDownLineList, 'length', 0) && (get(agentAggregatorDownLineMeta, 'num_page', 0) !== listConfig.current.page))) && (
            <div className='down-line-loader' ref={placeholder}>
              <CircularLoader isLoading />
            </div>
          )
        }
      </MyDownlineStyle>
      <ShareReferralCode referralCode={get(agentDetails, 'referral_code', '')} bottom='58px' />
      <InformationModal
        showModal={showModal}
        onCloseModal={handleToggleModal}
        isAggregatorAgent={isAggregatorAgent}
      />
      {
        snackBar.showBar && (
          <ShowSnackbar
            show={snackBar.showBar}
            text={snackBar.barMsg}
            error={snackBar.isBarMsgError}
          />
        )
      }
    </Container>
  )
}

export default connect(
  (state) => ({
    getDownlineLoader: state.Loading.GET_DOWNLINE,
    getDownlineChildListLoader: state.Loading.GET_DOWNLINE_CHILD,
    getAggregatorDownlineLoader: state.Loading.GET_AGGREGATOR_DOWNLINE,
    getAggregatorDownlineBusinessLoader: state.Loading.GET_AGGREGATOR_DOWNLINE_BUSINESS,

    agentDownLineSummary: state.User.agentDownLineList,
    agentDetails: state.User.agentDetails,
    agentDownLineSummaryStatus: state.User.agentDownLineListStatus,
    downlineChilds: state.User.agentDownLineChildList,
    agentDownLineChildMeta: state.User.agentDownLineChildMeta,
    agentDownLineChildStatus: state.User.agentDownLineListChildStatus,
    agentAggregatorBusiness: state.User.agentAggregatorBusiness,
    agentAggregatorBusinessStatus: state.User.agentAggregatorBusinessStatus,
    agentAggregatorDownLineList: state.User.agentAggregatorDownLineList,
    agentAggregatorDownLineMeta: state.User.agentAggregatorDownLineMeta,
    agentAggregatorDownLineListStatus: state.User.agentAggregatorDownLineListStatus
  }),
  {
    getDownline,
    getDownlineChild,
    resetUserStore,
    getAggregatorDownline,
    getAggregatorDownlineBusiness
  }
)(MyDownline)
