import { MyDownlineHeaderStyle } from './index.style'
import { CustomText } from '../../../../../../../components'
import { LANG_STRINGS } from '../../../../../../../lang'
import { formatMoney } from '../../../../../../../helpers/utility'
import get from 'lodash/get'

function MyDownlineHeaderCard (props) {
  const { isAggregatorAgent } = props

  const DownlineDetailCard = (title, value) => (
    <div className='downline-detail-card'>
      <CustomText>
        {title}
      </CustomText>
      <CustomText weight={800} top='0' size='16px'>
        {value}
      </CustomText>
    </div>
  )

  return (
    <MyDownlineHeaderStyle justify='space-between' align='center'>
      {
        DownlineDetailCard(LANG_STRINGS.downlines, get(props, 'data.downlines', ''))
      }
      {
        DownlineDetailCard(isAggregatorAgent ? LANG_STRINGS.premium : LANG_STRINGS.totalPoints, formatMoney(get(props, 'data.pointsEarned', ''), 0, ''))
      }
      {
        DownlineDetailCard(LANG_STRINGS.totalPolicies, get(props, 'data.policies', ''))
      }
    </MyDownlineHeaderStyle>
  )
}

export default MyDownlineHeaderCard
