import { Component } from 'react'
import { NoDownlineStyle } from './index.style'
import { ImageUrl } from '../../../../../../../images'
import { CustomText } from '../../../../../../../components'
import { LANG_STRINGS } from '../../../../../../../lang'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'

class NoDownline extends Component {
  renderDownlineNote = () => {
    const { activeLevel, isAggregatorAgent } = this.props
    if (isAggregatorAgent) {
      return (
        <div>
          <CustomText
            weight={800}
            bottom='10px'
            size='16px'
            color={AgentColorPallette.fontSecondary}
            textAlign='center'
          >
            {LANG_STRINGS.donotloseincome}
          </CustomText>
          <CustomText
            size='12px'
            color={AgentColorPallette.fontSecondary}
            textAlign='center'
          >
            {LANG_STRINGS.grabYourChanceToEarnMillions}
          </CustomText>
        </div>
      )
    } else {
      return (
        (activeLevel === 0) ? (
          <div>
            <CustomText weight={800} bottom='10px' size='16px' color={AgentColorPallette.fontSecondary} textAlign='center'>
              {LANG_STRINGS.donotMissOutExtraEarning}
            </CustomText>
            <CustomText size='12px' color={AgentColorPallette.fontSecondary} textAlign='center'>
              {LANG_STRINGS.grabYourChanceEarnMillions}
            </CustomText>
          </div>
        ) : (
          <CustomText size='12px' color={AgentColorPallette.fontSecondary} textAlign='center'>
            {LANG_STRINGS.increaseYourDownlineToEarnMore}
          </CustomText>
        )
      )
    }
  }

  render () {
    return (
      <NoDownlineStyle>
        <img className='downline-empty-box' src={ImageUrl.emptyBox} alt='' />
        <CustomText
          weight={800}
          size='16px'
          bottom='20px'
          top='20px'
          color={AgentColorPallette.fontSecondary}
        >
          {LANG_STRINGS.noDownlines}
        </CustomText>
        <div className='empty-downline-note'>
          {
            this.renderDownlineNote()
          }
        </div>
      </NoDownlineStyle>
    )
  }
}

export default NoDownline
