import { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { AvatarStyle } from './index.style'

class Avatar extends PureComponent {
  static propTypes = {
    imgUrl: PropTypes.string,
    name: PropTypes.string,
    width: PropTypes.string,
    height: PropTypes.string,
    isIcon: PropTypes.bool
  }

  getNameFirstLetter = (name = '') => {
    return name.charAt(0)
  }

  render () {
    const { width, height, name, imgUrl, isIcon } = this.props
    return (
      <AvatarStyle width={width} height={height} bgImg={imgUrl}>
        {
          isIcon ? <i className='far fa-user avatar-icon' />
            : !imgUrl && this.getNameFirstLetter(name)
        }
      </AvatarStyle>
    )
  }
}

export default Avatar
